  ".brand-wordmark{",
  "  margin-top:0;",
  "  color:#ffffff;",
  "  font-size:17px;",
  "  line-height:1.05;",
  "  font-weight:760;",
  "  letter-spacing:-.38px;",
  "  text-shadow:0 1px 8px rgba(5,24,56,.28);",
  "}",
  ".brand-subtitle{",
  "  margin-top:4px;",
  "  color:#c9ddf7;",
  "  font-size:10.5px;",
  "  line-height:1;",
  "  font-weight:500;",
  "  letter-spacing:.05px;",
  "  text-shadow:0 1px 5px rgba(6,30,68,.22);",
