  "      <div class=\"provider-pagination\">",
  "        <button class=\"page-btn\" disabled><svg class=\"icon\"><path d=\"m15 6-6 6 6 6\"/></svg></button>",
  "        <button class=\"page-btn active\">1</button>",
  "        <button class=\"page-btn\" disabled><svg class=\"icon\"><path d=\"m9 6 6 6-6 6\"/></svg></button>",
